import * as T from 'three';
// Centre rotation (owner 2026-11-15 "cho đổi center như clip dance đc ko?"; "đổi center cho những bài blackpink và huntrix
// thôi"). Songs whose `performances[slug].formation` block exists (the 4 BLACKPINK and 4 HUNTR/X songs) stage every group
// member on her own path from the dance clip: the child walks her member's path, the backups take the other members, two
// players are two members. Data: reports/center-rotation/HANDOFF-phase2.md, generated by
// reports/center-rotation/tools/make_blocks.py from trial-cac-full/work/<slug>-formation/formation.json.
//
// formation = {members:{name:{start:[x,y,z],moves:[{at,dur,to:[x,y,z],walk,pace?}]}}, centre:[[t0,t1,[names]]],
//  windows:[{t0,t1,tracks:{name:'lead'|asset|'groove'|'ready'}}], arch:{in,out,makers,over,cx,...}, depth:k, nudge:{dx,...}}
// Moves are the crew move format (crew.js place); y is 0 here (the ortho depth look is applied at draw time).

const smoother=(t,a,b)=>T.MathUtils.smootherstep(t,a,b),step=(t,a,b)=>T.MathUtils.smoothstep(t,a,b);
function trapz(tau,D){const r=Math.min(.25,D/4),A=D-r;if(tau<=0)return 0;if(tau>=D)return 1;if(tau<r)return tau*tau/(2*r)/A;if(tau<D-r)return (tau-r/2)/A;const u=D-tau;return 1-u*u/(2*r)/A;}
function angLerp(a,b,u){const d=((b-a+Math.PI)%(2*Math.PI)+2*Math.PI)%(2*Math.PI)-Math.PI;return a+d*u;}

// Position on a member path at song time t: the same walk maths as crew.js place() (constant speed, 0.25 s ease at the ends,
// turn to the way she goes over 0.35 s). pace 'quick' (fast swaps kept at the clip's timing): a quick side step, no turn.
// out: {x,z,yaw,walk (0..1 overlay weight),phase (leg phase),quick}
export function pathAt(path,t,out={}){
 let [x,,z]=path.start;let yaw=0,ww=0,phase=0,quick=false;
 if(t!=null)for(const m of path.moves){
  if(m.walk&&t>=m.at-.25&&t<m.at){ww=Math.max(ww,step(t,m.at-.25,m.at));quick=m.pace==='quick';}
  if(t<m.at)break;const to=m.to;
  if(m.walk){const fx=x,fz=z,dx=to[0]-fx,dz=to[2]-fz,L=Math.hypot(dx,dz),tau=t-m.at,u=trapz(tau,m.dur),travel=Math.atan2(dx,dz),q=m.pace==='quick';x=fx+dx*u;z=fz+dz*u;
   if(!q)yaw=tau>=m.dur?0:tau<.35?angLerp(0,travel,step(tau,0,.35)):tau>m.dur-.35?angLerp(travel,0,step(tau,m.dur-.35,m.dur)):travel;else yaw=0;
   if(tau<m.dur+.3){const w=tau<m.dur?1:1-step(tau,m.dur,m.dur+.3);if(w>=ww){ww=w;quick=q;}phase=2*Math.PI*L*u/(q?.42:.62);}}
  else{const p=smoother(t,m.at,m.at+m.dur);x+=(to[0]-x)*p;z+=(to[2]-z)*p;}
 }
 out.x=x;out.z=z;out.yaw=yaw;out.walk=ww;out.phase=phase;out.quick=quick;return out;
}
// interval weight with soft edges (windows, groove, ready)
export function windowWeight(t,a,b,f=.3){if(t==null||t<a-f||t>b+f)return 0;return step(t,a-f,a)*(1-step(t,b,b+f));}

// Members of the two players and the crew, by name. Two players: the host's pick first so both iPads agree; a guest on the
// host's member (or in no member set) takes the next free member's path.
export function castMembers(order,mine,theirs,duo){
 const own=c=>order.includes(c)?c:null;
 if(!duo){const me=own(mine)||order[0];return {me,partner:null,crew:order.filter(c=>c!==me)};}
 const host=duo.side==='L'?mine:theirs,guest=duo.side==='L'?theirs:mine;
 let a=own(host),b=own(guest);if(!a)a=order.find(c=>c!==b)||order[0];if(!b||b===a)b=order.find(c=>c!==a);
 const me=duo.side==='L'?a:b,partner=duo.side==='L'?b:a;return {me,partner,crew:order.filter(c=>c!==me&&c!==partner)};
}

// The child must stay visible: when another member stands in front of her she steps aside to the least covered spot.
// Precomputed at 10 Hz per song and per player: a pure function of t.
export function nudgeTrack(paths,who,dur,opt={}){
 // cost of standing at (x+dx, z+dz): covered by members in front (closer by > .1) within .34, bumping members on her row
 // within .26, the step itself (forward steps cost more) and changing the step (so she never darts across the group);
 // the cheapest sequence of steps over the song (Viterbi, 10 Hz, stage edge ±.9), then eased over ~.4 s
 const dt=.1,n=Math.ceil((dur+2)/dt)+1,o={},p={},M=opt.max??.6,others=Object.entries(paths).filter(([m])=>m!==who);
 const C=[];for(const dz of [0,.08,.15])for(let k=-M;k<=M+1e-9;k+=.05)C.push([Math.round(k*100)/100,dz]);const K=C.length;
 let prev=new Float64Array(K).fill(0);for(let c=0;c<K;c++)prev[c]=C[c][0]||C[c][1]?1e3:0;
 const back=new Array(n),cur=new Float64Array(K);
 for(let i=0;i<n;i++){const t=i*dt-1;pathAt(paths[who],t,o);const free=opt.skip?.some(([a,b])=>t>a-.6&&t<b+.6);// contact moves (the arch) keep their exact spots
  const ps=others.map(([,path])=>{pathAt(path,t,p);return [p.x,p.z];});const bk=new Int16Array(K);
  for(let c=0;c<K;c++){const [dx,dz]=C[c];let e;
   if(free)e=dx||dz?1e3:0;else{const x=o.x+dx,z=Math.min(0,o.z+dz);if(Math.abs(x)>.9)e=1e9;else{e=Math.abs(dx)*.5+dz*1.2;for(const [px,pz] of ps){const ax=Math.abs(x-px),d=pz-z;if(d>.1)e+=3*Math.max(0,.34-ax);else if(Math.abs(d)<=.12)e+=2*Math.max(0,.26-ax);}}}
   let best=1e18,bi=0;for(let q=0;q<K;q++){const v=prev[q]+3*Math.abs(C[q][0]-dx)+3*Math.abs(C[q][1]-dz);if(v<best){best=v;bi=q;}}cur[c]=best+e;bk[c]=bi;}
  back[i]=bk;prev=Float64Array.from(cur);}
 const rx=new Float32Array(n),rz=new Float32Array(n);let c=0;for(let q=1;q<K;q++)if(prev[q]<prev[c])c=q;
 for(let i=n-1;i>=0;i--){rx[i]=C[c][0];rz[i]=C[c][1];c=back[i][c];}
 const ease=a=>{const out=new Float32Array(n),R=4;for(let i=0;i<n;i++){let s=0,w=0;for(let k=-R;k<=R;k++){const j=Math.min(n-1,Math.max(0,i+k)),g=Math.exp(-.5*(k/(R/2))**2);s+=a[j]*g;w+=g;}out[i]=s/w;}return out;};
 const ox=ease(rx),oz=ease(rz),at=(a,t)=>{if(t==null)return 0;const f=Math.min(n-1,Math.max(0,(t+1)/dt)),i=Math.floor(f),j=Math.min(n-1,i+1),u=f-i;return a[i]+(a[j]-a[i])*u;};
 const fn=t=>at(ox,t);fn.z=t=>at(oz,t);return fn;
}
// Centre hint for the MV director: x of the centre member(s) at t (members' path x, the mean for an inner pair).
export function centreHint(form,paths,offsets={}){
 const list=(form.centre||[]).map(([a,b,ms])=>({a,b,ms})),o={};
 return t=>{const c=list.find(e=>t>=e.a&&t<e.b)||list[list.length-1];if(!c)return null;let s=0,n=0;for(const m of c.ms){if(!paths[m])continue;pathAt(paths[m],t,o);s+=o.x+(offsets[m]?.(t)||0);n++;}return n?s/n:null;};
}

// --- the child's own avatar (wardrobe variants): walk/step legs, standing (ready) or light groove, arch arms ---------------
const E=new T.Euler(),Q=new T.Quaternion(),W=new T.Quaternion(),DEG=Math.PI/180;
const LEGS=['hips','spine','leftUpperLeg','rightUpperLeg','leftLowerLeg','rightLowerLeg','leftFoot','rightFoot'];
const STAND=['hips','spine','chest','upperChest','neck','head','leftShoulder','rightShoulder','leftUpperArm','rightUpperArm','leftLowerArm','rightLowerArm','leftHand','rightHand','leftUpperLeg','rightUpperLeg','leftLowerLeg','rightLowerLeg','leftFoot','rightFoot','leftToes','rightToes'];
// same poses as independent-crew-rig.js ovPose (walk legs; standing with the arms down)
function pose(name,walk,ph,stride,q){let x=0,y=0,z=0;
 if(name==='leftUpperArm')z=-73*DEG;else if(name==='rightUpperArm')z=73*DEG;else if(name==='leftLowerArm')y=-10*DEG;else if(name==='rightLowerArm')y=10*DEG;
 if(walk){const sn=Math.sin(ph),cs=Math.cos(ph),kl=32*DEG*stride*Math.pow(Math.max(0,cs),1.3),kr=32*DEG*stride*Math.pow(Math.max(0,-cs),1.3);
  if(name==='hips')y=4*DEG*sn*stride;else if(name==='spine')y=-3*DEG*sn*stride;else if(name==='leftUpperLeg')x=-24*DEG*sn*stride;else if(name==='rightUpperLeg')x=24*DEG*sn*stride;
  else if(name==='leftLowerLeg')x=kl;else if(name==='rightLowerLeg')x=kr;else if(name==='leftFoot')x=-.4*kl;else if(name==='rightFoot')x=-.4*kr;}
 E.set(x,y,z,'XYZ');return q.setFromEuler(E);}
// walk: legs step (the arms keep dancing); stand: weight toward the standing pose (ready 1, groove ~.6)
export function leadOverlay(humanoid,walk,phase,quick,stand){
 if(walk>0)for(const n of LEGS){const b=humanoid.getNormalizedBoneNode(n);if(!b)continue;const s=pose(n,true,phase,quick?.6:1,Q);if(n==='spine'||n==='hips'){W.copy(b.quaternion).multiply(s);b.quaternion.slerp(W,walk);}else b.quaternion.slerp(s,walk);}
 if(stand>0)for(const n of STAND){const b=humanoid.getNormalizedBoneNode(n);if(!b)continue;b.quaternion.slerp(pose(n,false,0,1,Q),stand);}
}
// Arch maker (How You Like That 2:14.8-2:16.5) when the child is one of the two members who make the arch: the same body
// settle and two-bone arm IK as the crew (independent-crew-rig.js), on the child's raw arm bones after vrm.update.
const ARCH_BODY=['hips','spine','chest','upperChest','neck','head','leftUpperLeg','rightUpperLeg','leftLowerLeg','rightLowerLeg','leftFoot','rightFoot','leftToes','rightToes'];
export function leadArchBody(humanoid,a,w){for(const n of ARCH_BODY){const b=humanoid.getNormalizedBoneNode(n);if(!b)continue;pose(n,false,0,1,Q);
 if(n==='spine'||n==='chest'){E.set((a.lean||0)*.5*DEG,0,0,'XYZ');Q.multiply(W.setFromEuler(E));}else if((n==='leftFoot'||n==='rightFoot')&&a.toe){E.set(a.toe*DEG,0,0,'XYZ');Q.multiply(W.setFromEuler(E));}
 b.quaternion.slerp(Q,w);}}
const iS=new T.Vector3(),iE=new T.Vector3(),iH=new T.Vector3(),iT=new T.Vector3(),iU=new T.Vector3(),iN=new T.Vector3(),iE2=new T.Vector3(),iA=new T.Vector3(),iB=new T.Vector3(),iq=new T.Quaternion(),iw=new T.Quaternion(),ip=new T.Quaternion(),il=new T.Quaternion();
function turnBone(node,from,to,w){iq.setFromUnitVectors(from,to);node.getWorldQuaternion(iw);iw.premultiply(iq);node.parent.getWorldQuaternion(ip);il.copy(ip.invert()).multiply(iw);node.quaternion.slerp(il,w);node.updateWorldMatrix(false,true);}
export function armIK(humanoid,side,target,pole,w){const up=humanoid.getRawBoneNode(side+'UpperArm'),lo=humanoid.getRawBoneNode(side+'LowerArm'),ha=humanoid.getRawBoneNode(side+'Hand');if(!up||!lo||!ha||!target)return;
 up.getWorldPosition(iS);lo.getWorldPosition(iE);ha.getWorldPosition(iH);const a=iS.distanceTo(iE),b=iE.distanceTo(iH);iU.subVectors(target,iS);const d=T.MathUtils.clamp(iU.length(),Math.abs(a-b)+1e-3,a+b-1e-3);iU.normalize();iT.copy(iS).addScaledVector(iU,d);
 iN.subVectors(pole||iE,iS);iN.addScaledVector(iU,-iN.dot(iU));if(iN.lengthSq()<1e-8)iN.set(0,-1,0).addScaledVector(iU,-iU.y);iN.normalize();
 const c=T.MathUtils.clamp((a*a+d*d-b*b)/(2*a*d),-1,1);iE2.copy(iS).addScaledVector(iU,a*c).addScaledVector(iN,a*Math.sqrt(1-c*c));
 turnBone(up,iA.subVectors(iE,iS).normalize(),iB.subVectors(iE2,iS).normalize(),w);
 lo.getWorldPosition(iE);ha.getWorldPosition(iH);turnBone(lo,iA.subVectors(iH,iE).normalize(),iB.subVectors(iT,iE).normalize(),w);}
export function archWeightOf(a,t){if(!a||t==null)return 0;return smoother(t,a.in[0],a.in[1])*(1-smoother(t,a.out[0],a.out[1]));}
// wrist targets over the head of the member under the arch (same numbers as crew.js archFor)
const top=new T.Vector3(),sh=new T.Vector3();
export function archTargets(a,side,head,scaleY,makerHumanoid,out){head.getWorldPosition(top);
 const cx=(a.cx||0)+T.MathUtils.clamp(top.x-(a.cx||0),-(a.follow??.05),a.follow??.05),y=(a.wristY??1.18)*scaleY,z=(a.zOver??0)+(a.z??-.15),reach=a.gap??.06;
 makerHumanoid.getRawBoneNode(side>0?'leftUpperArm':'rightUpperArm')?.getWorldPosition(sh);
 out.hands=[0,1].map(k=>new T.Vector3(cx-side*reach,y,z+(k?1:-1)*side*(a.spread??.035)));out.pole=new T.Vector3(sh.x-side*.25,sh.y-.10,sh.z);return out;}
